fn extract_rear_chars(l: &Vec<Vec<char>>) -> Vec<char> {
    // Requires that the input vector is not empty and that each inner vector has at least one character
    // Ensures that the output vector has the same length as the input vector
    // and that each character in the output vector is the last character of the corresponding inner vector
    #[verus]
    requires(!l.is_empty() && l.iter().all(|inner| !inner.is_empty()));
    ensures(|result: &Vec<char>| {
        result.len() == l.len() && 
        (0..l.len()).all(|i| result[i] == *l[i].last().unwrap())
    });
    let result = l.iter()
        .map(|inner| *inner.last().unwrap()) // Get the last character of each inner vector
        .collect(); // Collect the results into a new vector
    result
}

fn main() {
    // Example usage
    let input = vec![
        vec!['a', 'b', 'c'],
        vec!['d', 'e'],
        vec!['f', 'g', 'h', 'i'],
    ];
    
    let result = extract_rear_chars(&input);
    println!("{:?}", result); // Output: ['c', 'e', 'i']
}